// context-bar: the context window as one stacked bar above the prompt,
// split into the same categories and theme colors /context uses.

// Whether the bar shows; saved in $.store so the toggle survives restarts
let isOn = true
// The last breakdown from $.session.usage, or null before the first one
let breakdown = null
// True while a breakdown request is in flight, so bursts fold into one
let isMeasuring = false

// Glyph per row kind: solid for what's used, light shade for free space,
// medium shade for the autocompact buffer
const GLYPH = { used: '█', free: '░', buffer: '▒' }

// 12345 -> "12.3k", 1234567 -> "1.2M"
function fmt(n) {
  if (n >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M'
  if (n >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'k'
  return String(n)
}

// Split `width` cells across rows by tokens, largest remainder first.
// Every row with tokens gets at least one cell, so small categories stay visible.
function allocate(rows, width) {
  const total = rows.reduce((sum, r) => sum + r.tokens, 0)
  if (total <= 0 || width <= 0) return rows.map(() => 0)
  const exact = rows.map((r) => (r.tokens / total) * width)
  const cells = exact.map((x, i) => (rows[i].tokens > 0 ? Math.max(1, Math.floor(x)) : 0))
  let left = width - cells.reduce((a, b) => a + b, 0)
  const order = exact.map((x, i) => i).sort((a, b) => (exact[b] % 1) - (exact[a] % 1))
  for (let k = 0; left > 0 && k < order.length * 2; k++) {
    const i = order[k % order.length]
    if (rows[i].tokens > 0) { cells[i] += 1; left -= 1 }
  }
  // The minimum of one cell can overshoot on a narrow band: take back from the widest
  while (left < 0) {
    const widest = cells.indexOf(Math.max(...cells))
    if (cells[widest] <= 1) break
    cells[widest] -= 1
    left += 1
  }
  return cells
}

// Ask Claude Code for the /context breakdown. 'summary' estimates locally and
// sends no token-count requests, so it's free to run after every turn.
async function measure($) {
  if (!isOn || isMeasuring) return
  isMeasuring = true
  try {
    const usage = await $.session.usage({ breakdown: 'summary' })
    breakdown = usage.context.breakdown ?? null
    $.ui.invalidate('ui.render')
  } finally {
    isMeasuring = false
  }
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    const saved = await $.store.get('isOn')
    if (typeof saved === 'boolean') isOn = saved
    await measure($)
    await $.command.register({
      name: 'context-bar',
      description: 'Show or hide the context bar above the prompt',
      argumentHint: '[on|off]',
      immediate: true,
    })
    return next(e)
  })

  // After each turn, and when the figures move
  on('session.measure', async ($, e, next) => {
    await measure($)
    return next(e)
  })

  // After /clear, /resume, /branch and compaction the window starts over
  on('classic.SessionStart', async ($, e, next) => {
    breakdown = null
    await measure($)
    return next(e)
  })

  on('command.run', { command: 'context-bar' }, async ($, e) => {
    const arg = (e.args || '').trim().toLowerCase()
    isOn = arg === 'on' ? true : arg === 'off' ? false : !isOn
    await $.store.set('isOn', isOn)
    if (isOn) await measure($)
    $.ui.invalidate('ui.render')
    $.ui.toast('Context bar ' + (isOn ? 'on' : 'off'))
    return {}
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // Hidden, nothing measured yet, or a survey wants the band: pass
    if (!isOn || !breakdown || e.props.hasSurvey) return next(e)
    const { Box, Text } = $.ui.resolve(e)

    // Deferred tool schemas sit outside the window, as in /context's grid
    const rows = breakdown.categories.filter((c) => c.kind !== 'deferred')
    const width = Math.max(10, e.props.bodyColumns)
    const cells = allocate(rows, width)

    const bar = Box({
      key: 'bar',
      flexDirection: 'row',
      children: rows
        .map((r, i) =>
          cells[i] > 0
            ? Text({ key: 'seg-' + i, color: r.color, children: [(GLYPH[r.kind] ?? '█').repeat(cells[i])] })
            : null,
        )
        .filter(Boolean),
    })

    // One line: the total, then a swatch, name and size per category
    const used = rows.filter((r) => r.kind === 'used')
    const legend = Box({
      key: 'legend',
      flexDirection: 'row',
      flexWrap: 'wrap',
      columnGap: 2,
      children: [
        Text({
          key: 'total',
          bold: true,
          wrap: 'truncate',
          children: [fmt(breakdown.totalTokens) + '/' + fmt(breakdown.rawMaxTokens) + ' ' + breakdown.percentage + '%'],
        }),
        ...used.map((r, i) =>
          Box({
            key: 'leg-' + i,
            flexDirection: 'row',
            flexShrink: 0,
            children: [
              Text({ key: 'sw', color: r.color, children: ['■ '] }),
              Text({ key: 'nm', dimColor: true, wrap: 'truncate', children: [r.name + ' ' + fmt(r.tokens)] }),
            ],
          }),
        ),
      ],
    })

    const mine = Box({ key: 'context-bar', flexDirection: 'column', children: e.props.maxRows >= 2 ? [bar, legend] : [bar] })

    // Keep whatever mods after this one draw in the band, under the bar
    const theirs = await next(e)
    return theirs ? Box({ flexDirection: 'column', children: [mine, theirs] }) : mine
  })
}

